package app.streamnest;
import org.junit.Test;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicLong;
public class RangeTraceTest {
 @Test public void distinguishesWaitingFromDeliveryWithoutAbsoluteOffsets() throws Exception {AtomicLong clock=new AtomicLong();RangeTrace trace=new RangeTrace(clock::get);long id=trace.open(50,99,100);trace.waiting(id,50);clock.set(500000000L);assertEquals(500,trace.snapshot().getLong("rangeWaitMs"));assertEquals("waiting",trace.snapshot().getString("rangeState"));trace.state(id,"reading");trace.served(id,60,10);assertEquals("serving",trace.snapshot().getString("rangeState"));assertEquals(60,trace.snapshot().getInt("rangeStartPercent"));assertEquals(10,trace.snapshot().getInt("rangeServedBytes"));assertFalse(trace.snapshot().has("positionMs"));trace.close(id);assertEquals(0,trace.snapshot().getInt("rangeActiveReaders"));}
 @Test public void trackingIsBoundedAndLateClosuresDoNotHideActiveReads() throws Exception {RangeTrace trace=new RangeTrace(System::nanoTime);for(int i=0;i<20;i++)trace.open(i,99,100);assertEquals(8,trace.snapshot().getInt("rangeActiveReaders"));trace.close(1);assertEquals(8,trace.snapshot().getInt("rangeActiveReaders"));assertEquals(20,trace.snapshot().getInt("rangeRequests"));}
 @Test public void timeoutSurvivesClosure() throws Exception {RangeTrace trace=new RangeTrace(System::nanoTime);long id=trace.open(0,99,100);trace.state(id,"timeout");trace.close(id);assertEquals("timeout",trace.snapshot().getString("rangeState"));assertEquals(100,RangeTrace.percent(Long.MAX_VALUE,1));}
}
